package com.bank.uuidkey.id;

import java.security.SecureRandom;
import java.util.UUID;

// Generates RFC 9562 UUIDv7: 48-bit millisecond timestamp + version/variant + random.
// The leading timestamp makes ids approximately time-ordered → insert locality.
public class UuidV7Generator {
    private static final SecureRandom RANDOM = new SecureRandom();

    public UUID generate() {
        long timestampMillis = System.currentTimeMillis();     // 48-bit time prefix
        byte[] bytes = new byte[16];
        RANDOM.nextBytes(bytes);

        // Bytes 0..5: 48-bit big-endian timestamp (time-ordered prefix)
        bytes[0] = (byte) (timestampMillis >>> 40);
        bytes[1] = (byte) (timestampMillis >>> 32);
        bytes[2] = (byte) (timestampMillis >>> 24);
        bytes[3] = (byte) (timestampMillis >>> 16);
        bytes[4] = (byte) (timestampMillis >>> 8);
        bytes[5] = (byte) timestampMillis;

        // Set version 7 in the high nibble of byte 6
        bytes[6] = (byte) ((bytes[6] & 0x0F) | 0x70);
        // Set IETF variant (10xx) in the high bits of byte 8
        bytes[8] = (byte) ((bytes[8] & 0x3F) | 0x80);

        long msb = 0, lsb = 0;
        for (int i = 0; i < 8; i++) msb = (msb << 8) | (bytes[i] & 0xFF);
        for (int i = 8; i < 16; i++) lsb = (lsb << 8) | (bytes[i] & 0xFF);
        return new UUID(msb, lsb);
    }
}
