package com.bank.uuidkey.service;

import com.bank.uuidkey.id.UuidV7Generator;
import com.bank.uuidkey.model.Transaction;
import com.bank.uuidkey.repository.TransactionRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.UUID;

@Service
public class TransactionService {
    private static final Logger log = LoggerFactory.getLogger(TransactionService.class);
    private final TransactionRepository repo;
    private final UuidV7Generator idGen = new UuidV7Generator();

    public TransactionService(TransactionRepository repo) { this.repo = repo; }

    public Transaction record(String accountId, BigDecimal amount) {
        UUID id = idGen.generate();   // time-ordered → appends near right edge of index
        Transaction txn = new Transaction(id, accountId, amount);
        Transaction saved = repo.save(txn);
        log.info("Recorded txn {} for {} amount {} (UUIDv7 time-ordered, low fragmentation)",
                 id, accountId, amount);
        return saved;
    }
}
